SELECT ppc.consume_record_id, ppc.order_id, ppc.trade_type_id, ppc.record_money, ppc.record_time, ppc.record_status, ppc.record_delete, ppc.record_after_money, ppc.record_payorder, oob.order_status oob.pay_code, oob.order_refund_status, oob.order_return_status FROM ${database.prefix.payment}hou_pay_consume_record ppc LEFT JOIN ${database.prefix.order}hou_order_base oob ON oob.payment_number = ppc.order_id WHERE user_id = #{userId}
and trade_type_id in (1,5)
and trade_type_id = #{tradeTypeId}
and record_delete = 0 order by record_time desc limit 10

