mapper.select:
select record_status
from ${database.prefix.payment}hou_pay_consume_record
where order_id = #{orderId}
  and user_id = #{userId}
  and user_type = 2

SELECT abc.shop_name AS shopName, abc.shop_id as shopId, abc.cardPayment, abc.balancePayment, abc.communicationsPayment, abc.weChatOnePayment, abc.weChatTwoPayment, abc.alipayPayment, abc.voucherPrice, abc.orderRptPrice, abc.shippingFee, abc.totalPayment, ccc.refundMoney FROM (SELECT ab.shop_name,ab.shop_id, sum( CASE ab.pay_code WHEN '卡支付' THEN ab.payprices WHEN '支付宝+卡' THEN ab.payprices * c.trade_payment_recharge_card / (c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card ) WHEN '微信+卡-10025054' THEN ab.payprices * c.trade_payment_recharge_card / (c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card) WHEN '微信+卡-1498662282' THEN ab.payprices * c.trade_payment_recharge_card /( c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card) ELSE '0' END ) AS cardPayment, sum( CASE ab.pay_code WHEN '余额' THEN ab.payprices ELSE '0' END ) AS balancePayment, sum( CASE ab.pay_code WHEN '通联' THEN ab.payprices ELSE '0' END ) AS communicationsPayment, sum( CASE ab.pay_code WHEN '微信-10025054' THEN ab.payprices WHEN '微信+卡-10025054' THEN ab.payprices * c.trade_third_party_amount / (c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card) ELSE '0' END ) AS weChatOnePayment, sum( CASE ab.pay_code WHEN '微信-1498662282' THEN ab.payprices WHEN '微信+卡-1498662282' THEN ab.payprices * c.trade_third_party_amount / (c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card) ELSE '0' END ) AS weChatTwoPayment, sum( CASE ab.pay_code WHEN '支付宝' THEN ab.payprices WHEN '支付宝+卡' THEN ab.payprices * c.trade_third_party_amount / (c.trade_third_party_amount + trade_payment_money + c.trade_payment_recharge_card) ELSE '0' END ) AS alipayPayment, sum( ab.voucher_price ) AS voucherPrice, sum( ab.order_rpt_price ) AS orderRptPrice, sum( ab.shipping_fee ) AS shippingFee, sum( ab.goods_price * ab.order_goods_num + shipping_fee - ab.voucher_price ) AS totalPayment FROM ( SELECT a.ordeR_id, b.goods_price, b.order_goods_num, b.order_goods_amount AS '订单总金额', b.voucher_price, b.order_rpt_price, b.order_goods_payment_amount payprices, a.shop_name, a.shop_id, a.order_from AS '订单来源', CASE a.pay_code WHEN 1 THEN '余额' WHEN 2 THEN '支付宝' WHEN 3 THEN CONCAT( '微信', IF ( a.order_from = 2, '-10025054', '-1498662282' )) WHEN 4 THEN '通联' WHEN 7 THEN '支付宝+卡' WHEN 8 THEN CONCAT( '微信+卡', IF ( a.order_from = 3, '-1498662282', '-10025054' )) ELSE '卡支付' END pay_code, a.order_finished_time '订单完成时间', b.shipping_fee, a.order_refund_amount '退款金额' FROM ${database.prefix.order}hou_order_base a, ${database.prefix.order}hou_order_goods b WHERE a.order_id = b.order_id
AND a.payment_time >= #{param.startTime}
AND a.payment_time <=#{param.endTime}
AND a.order_status BETWEEN 2 AND 6
and a.shop_name like concat('%',#{param.shopName},'%')
) ab LEFT JOIN ${database.prefix.payment}hou_pay_consume_trade c ON ab.order_id = c.order_id GROUP BY ab.shop_name ) abc LEFT JOIN ( SELECT sum( return_cash ) refundMoney, shop_name FROM ${database.prefix.order}hou_order_return WHERE return_state in (2,4,5,8,13)
and return_finish_time >= #{param.startTime}
and return_finish_time <=#{param.endTime}
group by shop_id) ccc ON abc.shop_name = ccc.shop_name

SELECT order_id, trade_type_id, user_nickname, record_money, record_title, user_type, record_status, record_paytime, record_date, record_desc, record_payorder FROM ${database.prefix.payment}hou_pay_consume_record where user_type = 1
and trade_type_id = #{param.tradeTypeId}
and user_nickname like concat ('%', #{param.userNickname},'%')
and record_payorder >= #{param.recordPayorder}
and record_paytime >= #{param.startTime}
and #{param.afterTime} >= record_paytime
order by record_date desc,record_paytime desc

SELECT sum( CASE plus_or_minus WHEN '0' THEN ( - 1 * record_money ) WHEN '1' THEN record_money END ) AS record_money FROM ${database.prefix.payment}hou_pay_consume_record WHERE order_id IN
#{orderId}
and user_id = #{userId} and record_withdraw = 0

SELECT sum( CASE plus_or_minus WHEN '0' THEN ( - 1 * os_commis_amount ) WHEN '1' THEN os_commis_amount END ) AS record_money FROM ${database.prefix.payment}hou_pay_consume_record WHERE order_id IN
#{orderId}
and user_id = #{userId} and record_withdraw = 0
